// Modern approach with Activity Result API
val launcher = registerForActivityResult(
    ActivityResultContracts.RequestPermission()
) { isGranted ->
    if (isGranted) {
        openCamera()
    } else {
        showDeniedMessage()
    }
}

// Check & request
when {
    ContextCompat.checkSelfPermission(ctx, CAMERA)
        == PERMISSION_GRANTED -> openCamera()
    shouldShowRequestPermissionRationale(CAMERA)
        -> showRationale()
    else -> launcher.launch(CAMERA)
}

@Composable
fun CameraScreen() {
    val context = LocalContext.current
    val launcher = rememberLauncherForActivityResult(
        ActivityResultContracts.RequestPermission()
    ) { granted ->
        if (granted) openCamera(context)
    }

    Button(onClick = {
        launcher.launch(Manifest.permission.CAMERA)
    }) {
        Text("Take Photo")
    }
}

val permissions = arrayOf(
    Manifest.permission.CAMERA,
    Manifest.permission.RECORD_AUDIO
)

val launcher = rememberLauncherForActivityResult(
    ActivityResultContracts.RequestMultiplePermissions()
) { results ->
    val allGranted = results.values.all { it }
    if (allGranted) {
        startVideoCall()
    } else {
        // Handle partial grants
        val hasCamera = results[Manifest.permission.CAMERA] == true
        val hasMic = results[Manifest.permission.RECORD_AUDIO] == true
    }
}
